            var ps3 = {gender:g, category_id:cid, need_filters:nf, page:pg, words:words, sort:sort, over:over, imei_ip:'2937357107', book_privacy:'1', read_preference:'0'};
            if (ct) ps3.category_type = ct;
            if (isTag) { ps3.tag_id = tid; delete ps3.category_id; }
            if (apiVer === 'v5') { ps3.book_preference='1'; ps3.from='4'; }
            qmSignParams(ps3, java);
            // 版本回退：v4 被 WAF 拒（405 HTML）时自动降级到 v5 / v3。
            // 三条在沙盒都是 401（路径存在、只是要登录态），所以回退不会引进死路径。
            var _ctPaths = isTag
