    } catch (e) { }
    // ⚠ value 为空【也要继续】—— 之前这里直接 return，导致"选了空值/没变"时
    //   连 refreshExplore 都不调，界面纹丝不动。现在空值只跳过赋值，不跳过刷新。
    if (value != null && String(value) !== "") { d[key] = String(value); }
    try { source.setVariable(JSON.stringify(d)); } catch (e) { }
