                   "sort": "排序", "line": "线路", "kind": "📚类型",
                   "exploreGroup": "📁分组" };
      var _t = String(_lbl[key] || "");
      // ⚠ 每个下拉要写的值【各不相同】：
      //    「📚类型」写类型本身（📕漫画），「平台」写平台名（漫画）。
      //    上一版图省事用同一个 _disp 写两个下拉 → 类型下拉被写成「漫画」，
      //    再切回来就变成「书旗」，越切越乱。分开写。
      if (_t !== "") {
        var _own = String(value);            // 这个下拉自己的值
        var _plat = "";                      // 需要同步给「平台」下拉的显示值
        if (key === "kind") {
          // 只回写【类型】下拉自己的值；src 的落点统一交给 exploreUrl 处理
          //（那里才知道"漫画全站"要把四个漫画平台合并，nhSetF 这层做不到）
          _plat = (_own === "📕漫画") ? "漫画" : (_own === "📖小说" ? "书旗" : "全部");
        }
        try {
          if (typeof infoMap !== "undefined" && infoMap && typeof infoMap.put === "function") {
            infoMap.put(_t, _own);
          } else if (typeof infoMap !== "undefined" && infoMap) {
            infoMap[_t] = _own;
          }
        } catch (e2) { }
        if (_plat !== "") {
          try {
            if (typeof infoMap !== "undefined" && infoMap && typeof infoMap.put === "function") {
              infoMap.put("平台", _plat);
            } else if (typeof infoMap !== "undefined" && infoMap) { infoMap["平台"] = _plat; }
          } catch (e3) { }
        }
      }
    } catch (e0) { }
    // ── 刷新 ──
    //   源码路径（ExploreAdapter.kt → reUiView → refreshExplore(item,…)）：
    //     clearExploreKindsCache() → exploreKinds()（重跑 exploreUrl）→ notifyItemChanged()
    //   所以只调【一个】java.refreshExplore()，它会清缓存+重跑+重建，下拉选项也跟着重算。
    //   ⚠ 曾经在这里连调 5 个 API，第二个起就在往已被销毁的 JS 上下文里写，
    //     把正在执行的回调打死 → 连第一个也没跑成 → 表现为「全空转」。

    // ── 刷新：一次，就这一次 ──
    //   clearExploreKindsCache() + exploreKinds()（重跑 exploreUrl）+ notifyItemChanged()
    //   → 平台/类型下拉的【选项列表】会跟着重算，这就是「切类型后下拉收窄」的实现。
    //
    // ⚠⚠ 调用完必须【立刻结束】，后面不能再碰 java.*：
    //   refreshExplore() 会重建 flexbox，旧 flexbox 被回收 →
    //   SourceLoginJsExtensions 里 callbackRef 是 WeakReference，callback 变 null →
    //   再调任何 java.* 都是静默空转。
    //   之前栽过两次：
    //     ① 一个 action 里连调 5 个刷新 API，后 4 个把正在执行的回调打死
    //     ② nhSetF 内部调一次 + action 字符串里又调一次（= 一次切换触发两次）
    try { java.refreshExplore(); } catch (e) { }

