        return (!isNaN(n) && n > 0 && n < 65536) ? String.fromCharCode(n) : "";
      }
      var M = { "nbsp": " ", "ensp": " ", "emsp": "　", "thinsp": " ", "hellip": "…",
                "mdash": "—", "ndash": "–", "ldquo": "“", "rdquo": "”", "lsquo": "‘", "rsquo": "’",
                "middot": "·", "times": "×", "laquo": "«", "raquo": "»", "copy": "©", "reg": "®",
                "lt": "<", "gt": ">", "amp": "&", "quot": "”", "apos": "'" };
