// ════════════════════════════════════════════════════════════════
// 结构化简介：数据模型（各平台只往里【塞值】，渲染器拼一次）
// ════════════════════════════════════════════════════════════════
// 重构前（2026-10-08 之前）：13 个分支各自 L.push("书号：" + v) 手拼标签文本，
//   收口再把这 90+ 处文本**解析回对象**、重新排序渲染 —— 数据在两条路上来回搬。
//   现在：分支只 nhPut(d, "书号", v) / nhBody(d, v)，字段名、顺序、单位归一、
//   空值省略、简介缩进全部由 nhRenderIntro 一处决定。
var NH_INTRO_STD = ["源站","书号","状态","登录状态","章节","最新","更新",
                    "分类","地区","题材",
                    "主角","别名",
                    "标签","评分","肉量","版本","在读","锁定","收藏","人气",
                    "字数"];
// 非标准叫法 → 标准叫法（各分支历史上自己写的那些五花八门的标签）
var NH_INTRO_REN = {
  // 只留【真同义词】。站方特有的元数据（肉量/评分/版本/在读/锁定/地区/题材）
  // 一律自己开一栏 —— 塞进「标签」会把不同含义的东西混成一栏，用户看到的是
  // 「标签：21.54%(中肉) 9.2分」，分不清哪个是哪个（2026-10-08 用户指出过）。
  "作者": "主角"
};
// 【直接丢弃】：App 会单独显示书名/标题，简介块里再放一遍是冗余
var NH_INTRO_DROP = ["书名", "标题"];
// 字数单位归一：243.3K / 1.2万 / 608.1万 / 约9.44万字（站方标注） → 统一成「X万字」
function nhWords(v) {
  var s = String(v == null ? "" : v).trim();
  if (s === "") { return ""; }
  s = s.replace(/（[^）]*）/g, "").replace(/\([^)]*\)/g, "").trim();
  var m = s.match(/^约?\s*([0-9.]+)\s*[kK]\b/);
  if (m) { return "约" + (parseFloat(m[1]) / 10).toFixed(1).replace(/\.0$/, "") + "万字"; }
  m = s.match(/^约?\s*([0-9.]+)\s*万/);
  if (m) { return m[1] + "万字"; }
  m = s.match(/^([0-9]+)\s*字/);
  if (m) { return m[1] + "字"; }
  m = s.match(/^([0-9]+)\s*$/);
  if (m) { return m[1] + "字"; }
  return s;
}
// 站方给的字数（19089580）→ 1909万字。站方原始值换算，不是估算。
function nhWan(n) {
  var v = parseInt(String(n == null ? "" : n).replace(/[^0-9]/g, ""), 10) || 0;
  if (v <= 0) { return ""; }
  return String(Math.round(v / 10000 * 10) / 10) + "万字";
}

function nhIntroNew() { return { f: {}, b: [] }; }
// 塞一个字段（同名字段自动合并，绝不丢数据）
function nhPut(d, k, v) {
  if (v === null || v === undefined) { return d; }
  var s = String(v).replace(/[\r\n]+/g, " ").trim();
  if (s === "") { return d; }
  var lab = NH_INTRO_REN[k] || k;
  if (d.f[lab]) { d.f[lab] = d.f[lab] + " " + s; } else { d.f[lab] = s; }
  return d;
}
// 塞简介正文（一段一段，按换行切，进去就 trim + 去掉前导全角空格）
function nhBody(d, v) {
  if (v === null || v === undefined) { return d; }
  var parts = String(v).split(/\r?\n/);
  for (var i = 0; i < parts.length; i++) {
    var t = parts[i].replace(/[\r\n]+/g, " ").replace(/^[\s　]+/, "").trim();
    if (t !== "") { d.b.push(t); }
  }
  return d;
}
