function nhRenderIntro(d, siteName) {
  var f = d.f, out = [], i, k;
  if (!f["源站"] && siteName) { f["源站"] = siteName; }
  if (f["状态"] === "完结" || f["状态"] === "全本") { f["状态"] = "已完结"; }
  else if (f["状态"] === "连载") { f["状态"] = "连载中"; }
  var w = nhWords(f["字数"]);
  if (w !== "") { f["字数"] = w; }
  if (f["章节"] && f["章节"].indexOf("章") < 0 && f["章节"].indexOf("页") < 0
      && f["章节"].indexOf("话") < 0) { f["章节"] += "章"; }
  for (k = 0; k < NH_INTRO_STD.length; k++) {
    if (f[NH_INTRO_STD[k]]) { out.push(NH_INTRO_STD[k] + "：" + f[NH_INTRO_STD[k]]); }
  }
  if (d.b.length) {
    out.push("简介：");
    for (i = 0; i < d.b.length; i++) { out.push("　　" + d.b[i]); }
  }
  return out.join("\n");
}

